import React from "react";
import type { Meta, StoryObj } from "@storybook/react";

import { useTheme } from "aihappey-components";
import type { AihUiTheme, ChatMessage } from "aihappey-types";

type ChatThemeProps = Parameters<AihUiTheme["Chat"]>[0];

type ChatStoryArgs = Omit<ChatThemeProps, "renderMessage" | "renderReactions"> & {
  showReactions?: boolean;
};

const makeTextMessage = (
  partial: Omit<ChatMessage, "content" | "createdAt"> & {
    text: string;
    createdAt?: string;
  }
): ChatMessage => {
  return {
    id: partial.id,
    role: partial.role,
    author: partial.author,
    createdAt: partial.createdAt ?? new Date("2026-01-01T12:00:00.000Z").toISOString(),
    content: [{ type: "text", text: partial.text }],
  };
};

const ChatStory = (args: ChatStoryArgs) => {
  const { Chat } = useTheme() as unknown as Pick<AihUiTheme, "Chat">;
  const { showReactions, ...chatProps } = args;

  return (
    <Chat
      {...chatProps}
      renderMessage={(msg: ChatMessage) => {
        const textPart = msg.content.find((p) => p.type === "text");
        const text = textPart && "text" in textPart ? textPart.text : "(non-text message)";

        return (
          <div style={{ padding: "6px 8px" }}>
            <strong style={{ marginRight: 6 }}>{msg.role.toUpperCase()}:</strong>
            <span>{text}</span>
          </div>
        );
      }}
      renderReactions={
        showReactions
          ? () => <div style={{ padding: "0 8px 8px", opacity: 0.7 }}>👍 2 � 👎 1</div>
          : undefined
      }
    />
  );
};

const meta = {
  title: "Chat",
  component: ChatStory,
  argTypes: {
    messages: { control: false },
    showReactions: { control: { type: "boolean" } },
    locale: { control: { type: "text" } },
  },
} satisfies Meta<typeof ChatStory>;

export default meta;
type Story = StoryObj<typeof meta>;

const defaultMessages: ChatMessage[] = [
  makeTextMessage({ id: "1", role: "user", text: "Hello", createdAt: "2026-01-01T12:00:00.000Z" }),
  makeTextMessage({
    id: "2",
    role: "assistant",
    author: "gpt-5.2",
    text: "Hi there!",
    createdAt: "2026-01-01T12:00:05.000Z",
  }),
];

export const Default: Story = {
  args: {
    messages: defaultMessages,
  },
};

export const WithReactions: Story = {
  args: {
    messages: [
      makeTextMessage({
        id: "1",
        role: "user",
        text: "This message has reactions",
        createdAt: "2026-01-01T12:01:00.000Z",
      }),
      makeTextMessage({
        id: "2",
        role: "assistant",
        author: "gpt-5.2",
        text: "React to this!",
        createdAt: "2026-01-01T12:01:05.000Z",
      }),
    ],
    showReactions: true,
  },
};

export const ComplexConversation: Story = {
  args: {
    messages: [
      makeTextMessage({
        id: "s1",
        role: "system",
        text: "You are a helpful assistant.",
        createdAt: "2026-01-01T12:02:00.000Z",
      }),
      makeTextMessage({
        id: "1",
        role: "user",
        text: "Explain quantum computing.",
        createdAt: "2026-01-01T12:02:05.000Z",
      }),
      makeTextMessage({
        id: "2",
        role: "assistant",
        author: "gpt-5.2",
        text: "Quantum computing uses quantum mechanics to process information.",
        createdAt: "2026-01-01T12:02:10.000Z",
      }),
      makeTextMessage({
        id: "3",
        role: "user",
        text: "How is it different from classical?",
        createdAt: "2026-01-01T12:02:15.000Z",
      }),
      makeTextMessage({
        id: "4",
        role: "assistant",
        author: "gpt-5.2",
        text:
          "Classical computers use bits (0 or 1), while quantum computers use qubits which can be both 0 and 1 at the same time (superposition).",
        createdAt: "2026-01-01T12:02:20.000Z",
      }),
    ],
  },
};

export const Empty: Story = {
  args: {
    messages: [],
  },
};

